fn solve(n: i8) -> Vec<char> {
    // We'll build a Vec<char> of length 6:
    // first three are 'A', 'B', 'C',
    // last three are the decimal digits of n (guaranteed to be in [100, 999]).

    let mut result = Vec::with_capacity(6);
    // Push the fixed prefix
    result.push('A');
    result.push('B');
    result.push('C');

    // Convert n to an unsigned so we can do digit extraction easily.
    // We know n is in [100, 999], fits in u8.
    let x = n as u8;

    // Extract the hundreds, tens, and ones digits.
    let hundreds = x / 100;
    let tens = (x / 10) % 10;
    let ones = x % 10;

    // Convert each digit to the corresponding char by adding to '0' (0x30).
    result.push((b'0' + hundreds) as char);
    result.push((b'0' + tens) as char);
    result.push((b'0' + ones) as char);

    result
}

